import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"61、【中孚】 兌下巽上","description":"子夏易傳 - 61、【中孚】 兌下巽上","frontmatter":{"title":"61、【中孚】 兌下巽上","description":"子夏易傳 - 61、【中孚】 兌下巽上"},"headers":[],"relativePath":"classics/zixia/063.md","filePath":"classics/zixia/063.md"}'),i={name:"classics/zixia/063.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_61、【中孚】-兌下巽上" tabindex="-1">61、【中孚】 兌下巽上 <a class="header-anchor" href="#_61、【中孚】-兌下巽上" aria-label="Permalink to “61、【中孚】 兌下巽上”">​</a></h1><p>卦辭：中孚，豚魚吉。利渉大川，利貞。</p><p>彖曰：中孚，柔在內而剛得中。說而巽，孚乃化邦也。豚魚吉，信及豚魚也。利渉大川，乗木舟虛也。中孚以利貞，乃應乎天也。</p><p>子夏：上柔在內，以接於下，而剛得中，柔接而相親，剛中而實信，就巽以從之，故得下柔奉之而剛中，以信而民，莫不化者也。中發之信，恆而及於豚魚，雖豚魚而信，不遺其微小焉，故吉也。利渉大川，乗木而無險也。君子虛其中，而施信於民，故得民之信而可以致重道逺也。信自於中利而以正，?於天地四時也，而況人乎。</p><p>象曰：澤上有風，中孚。君子以議獄緩死。</p><p>子夏：澤降而風加焉，相得澤行也。君子信行，庶其中，感而變化也。故議留其獄，不即其死。</p><p>初九，虞吉，有他不燕。</p><p>象曰：初九虞吉，志未變也。</p><p>子夏：中孚之故在乎初也。速而應感其誠也，故度其志未變，而往則信終而吉。志變而有作，不可感也已矣。後之而絶類也。何所安乎。</p><p>九二，鳴鶴在隂，其子和之，我有好爵，吾與爾縻之。</p><p>象曰：其子和之，中心願也。</p><p>子夏：鶴者陽明之物也。而守隂處內，修徳立誠，名達而隱也，上中孚也。求中信以致，雖居隂也，時亦索之。中心願與之為治，同志而相求也，故公家之有好爵，而相與縻之矣。君子之道在於進徳乎，無隱而不彰，上求下治之本也。故君子而求其母也。</p><p>六三，得敵，或鼓或罷，或泣或歌。</p><p>象曰：或鼓或罷，位不當也。</p><p>子夏：三與四皆為敵，三應於上，四巽於下，對而為敵，鼔以戰之。四附上而大不敢當也，或罷之矣。不勝而懼，或泣之矣。四不我爭，歡巳志獲，或歌之矣。柔徳之薄，不量其勢，不當於位，不正於分也。</p><p>六四，月幾望，馬匹亡，無咎。</p><p>象曰：馬匹亡，絶類上也。</p><p>子夏：得位上順而為五巽，隂盛得附，故無咎也。</p><p>九五，有孚攣如，無咎。</p><p>象曰：有孚攣如，位正當也。</p><p>子夏：四絶類而孚我，我亦有信。攣如，當其位正，雖得地而無咎。</p><p>上九，翰音登於天，貞兇。</p><p>象曰：翰音登於天，何可長也。</p><p>子夏：翰音為雞巽之象也，以其陽物巽隂而無力飛，必鳴也，登於天何可久乎。信不由中，而為極上，難終之約，其可乎。信而莫應，有聲而巳，正之兇也。</p>',24)])])}const f=a(i,[["render",r]]);export{m as __pageData,f as default};
